// ─────────────────────────────────────────────────────────────────────────────
// Build Synthetic Contact Events (Manual Test Trigger path)
// Emits a webhook-shaped HubSpot contact.creation batch for fictitious contacts.
// The mock lead retrieval resolves these IDs to synthetic contact records.
// ─────────────────────────────────────────────────────────────────────────────
const now = Date.now();
const ids = ['6100000001', '6100000002', '6100000003', '6100000004', '6100000005', '6100000006', '6100000007', '6100000008'];
const body = ids.map((id, i) => ({
  eventId: 820000000 + i, subscriptionId: 4400001, portalId: 99000001, appId: 5400001, occurredAt: now - (ids.length - i) * 1000,
  subscriptionType: 'contact.creation', attemptNumber: 0, objectId: Number(id), changeFlag: 'CREATED', changeSource: 'FORM',
}));
// One duplicate delivery and one event caused by this integration (loop guard).
body.push({ ...body[0], eventId: 820000099 });
body.push({ eventId: 820000100, subscriptionId: 4400002, portalId: 99000001, appId: 5400001, occurredAt: now, subscriptionType: 'contact.propertyChange', propertyName: 'hubspot_owner_id', objectId: 6100000001, changeSource: 'INTEGRATION', sourceId: '5400001' });

return [{ json: { headers: { 'content-type': 'application/json', 'user-agent': 'HubSpot Connect 2.0 (synthetic)' }, params: {}, query: {}, body, webhookUrl: 'https://n8n.example/webhook/hubspot/lead-assignment', executionMode: 'test' } }];

// ─────────────────────────────────────────────────────────────────────────────
// Parse & Validate Events
// Webhook runs  → mode "webhook": verify the HubSpot v3 signature, keep
//                 contact.creation (and form-driven workflow webhooks that post
//                 an objectId), drop changes made by this integration, and
//                 de-duplicate contact IDs.
// Schedule/manual without a body → mode "sweep": find unassigned contacts.
//
// Security note: HUBSPOT_APP_CLIENT_SECRET is read here only because an HMAC
// cannot be computed in an HTTP header field. It never leaves this node.
// ─────────────────────────────────────────────────────────────────────────────
const req = $input.first().json;
const cfg = req.config;
const isWebhook = req.body !== undefined && req.headers !== undefined;
if (!isWebhook) return [{ json: { mode: 'sweep', contactIds: [], counters: null, signature: 'n/a' } }];

const headers = Object.fromEntries(Object.entries(req.headers || {}).map(([k, v]) => [String(k).toLowerCase(), v]));
let signature = 'skipped (sandbox)';
if (!cfg.sandboxMode && cfg.requireSignature) {
  const sig = headers['x-hubspot-signature-v3'];
  const ts = headers['x-hubspot-request-timestamp'];
  if (!sig || !ts) throw new Error('Rejected: missing HubSpot v3 signature headers.');
  if (!Number.isFinite(Number(ts)) || Math.abs(Date.now() - Number(ts)) > 300000) throw new Error('Rejected: HubSpot request timestamp outside the 5-minute window.');
  let secret = '';
  try { secret = String($env.HUBSPOT_APP_CLIENT_SECRET || ''); } catch (e) { secret = ''; }
  if (!secret) throw new Error('Rejected: HUBSPOT_APP_CLIENT_SECRET is not set and REQUIRE_HUBSPOT_SIGNATURE is not false.');
  let crypto;
  try { crypto = require('crypto'); } catch (e) { throw new Error('Signature verification needs NODE_FUNCTION_ALLOW_BUILTIN=crypto.'); }
  const raw = typeof req.body === 'string' ? req.body : JSON.stringify(req.body);
  const expected = crypto.createHmac('sha256', secret).update(`POST${cfg.webhookPublicUrl || req.webhookUrl}${raw}${ts}`, 'utf8').digest('base64');
  const a = Buffer.from(String(sig));
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Rejected: HubSpot v3 signature mismatch.');
  signature = 'verified';
} else if (!cfg.sandboxMode) {
  signature = 'disabled (REQUIRE_HUBSPOT_SIGNATURE=false)';
}

let events = req.body;
if (typeof events === 'string') { try { events = JSON.parse(events); } catch (e) { events = []; } }
if (!Array.isArray(events)) events = events ? [events] : [];

const counters = { received: events.length, ignoredType: 0, selfInflicted: 0, duplicate: 0, accepted: 0 };
const ids = [];
for (const e of events) {
  const type = String(e?.subscriptionType || 'workflow.webhook');
  const id = String(e?.objectId ?? e?.hs_object_id ?? e?.properties?.hs_object_id ?? '');
  // Loop guard first: changes written by this integration never re-trigger assignment.
  if (cfg.hubspotAppId && String(e.sourceId || '') === cfg.hubspotAppId) { counters.selfInflicted += 1; continue; }
  if (!/^\d+$/.test(id) || !['contact.creation', 'workflow.webhook'].includes(type)) { counters.ignoredType += 1; continue; }
  if (ids.includes(id)) { counters.duplicate += 1; continue; }
  ids.push(id);
}
counters.accepted = ids.length;
return [{ json: { mode: 'webhook', contactIds: ids.slice(0, Math.min(100, cfg.maxLeadsPerRun)), counters, signature } }];

// ─────────────────────────────────────────────────────────────────────────────
// Mock Lead Retrieval (SANDBOX_MODE=true)
// Fictitious HubSpot contacts in the batch-read / search response shape.
// ─────────────────────────────────────────────────────────────────────────────
const ctx = $input.first().json;
const MIN = 60 * 1000;
const ago = (m) => new Date(Date.now() - m * MIN).toISOString();
const c = (id, p) => ({ id, properties: { hs_object_id: id, createdate: ago(5), lifecyclestage: 'lead', hubspot_owner_id: null, round_robin_assigned_at: null, hubspotscore: '20', state: null, ...p } });

const CATALOG = [
  c('6100000001', { firstname: 'Jordan', lastname: 'Smith', email: 'jordan@company.example', company: 'Company Example Ltd', country: 'US', state: 'NY', hubspotscore: '35' }),
  c('6100000002', { firstname: 'Avery', lastname: 'Lane', email: 'avery@brightline.example', company: 'Brightline Example', country: 'US', state: 'TX', hubspotscore: '82' }),
  c('6100000003', { firstname: 'Rowan', lastname: 'Price', email: 'rowan@cobalt.example', company: 'Cobalt Example', country: 'US', state: 'CA', hubspotscore: '15' }),
  c('6100000004', { firstname: 'Elena', lastname: 'Voss', email: 'elena@harbor.example', company: 'Harbor Example GmbH', country: 'DE', hubspotscore: '40' }),
  c('6100000005', { firstname: 'Kenji', lastname: 'Mori', email: 'kenji@summit.example', company: 'Summit Example KK', country: 'JP', hubspotscore: '55' }),
  c('6100000006', { firstname: 'Dana', lastname: 'Cole', email: 'dana@company.example', company: 'Company Example Ltd', country: 'US', state: 'MA', hubspot_owner_id: '84000001' }),
  c('6100000007', { firstname: 'Sky', lastname: 'Rivera', email: 'sky.rivera', company: 'Unknown', country: 'US' }),
  c('6100000008', { firstname: 'Morgan', lastname: 'Hale', email: 'morgan@lumen.example', company: 'Lumen Example', country: 'US', state: 'WA', hubspotscore: '28' }),
];

const results = ctx.mode === 'webhook' ? CATALOG.filter((x) => ctx.contactIds.includes(x.id)) : CATALOG.filter((x) => !x.properties.hubspot_owner_id);
return [{ json: { source: 'synthetic-fixtures', results } }];

// ─────────────────────────────────────────────────────────────────────────────
// Normalize Leads
// Flattens batch-read / search / sandbox responses into lead records, derives
// territory (TERRITORY_RULES) and score tier, and validates integrity:
// a valid email, not already owned (unless REASSIGN_UNAVAILABLE_OWNER and the
// owner is later found unavailable), not already assigned by this balancer.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const ctx = $('Parse & Validate Events').first().json;
const EMAIL_RE = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,63}$/i;

const SANDBOX_TERRITORIES = [
  { name: 'NA', countries: ['US', 'USA', 'CA'] },
  { name: 'EMEA', countries: ['GB', 'UK', 'DE', 'FR', 'NL', 'IE', 'ES', 'IT', 'SE'] },
  { name: 'APAC', countries: ['JP', 'IN', 'SG', 'AU', 'NZ', 'KR'] },
];
let territories = SANDBOX_TERRITORIES;
if (cfg.territoryRulesJson) {
  try { territories = JSON.parse(cfg.territoryRulesJson); } catch (e) { throw new Error('TERRITORY_RULES is not valid JSON.'); }
} else if (!cfg.sandboxMode) {
  territories = [];
}
territories = territories.map((t) => ({ name: String(t.name), countries: (t.countries || []).map((x) => String(x).toUpperCase()), states: (t.states || []).map((x) => String(x).toUpperCase()) }));
const territoryFor = (country, state) => {
  const C = String(country || '').toUpperCase();
  const S = String(state || '').toUpperCase();
  const t = territories.find((r) => r.countries.includes(C) && (!r.states.length || r.states.includes(S)));
  return t ? t.name : 'unmatched';
};

const raw = [];
for (const item of $input.all()) for (const r of Array.isArray(item.json.results) ? item.json.results : []) raw.push(r);

const stats = { mode: ctx.mode, retrieved: raw.length, invalidEmail: 0, alreadyOwned: 0, alreadyAssigned: 0, duplicate: 0, overCap: 0, accepted: 0 };
const seen = new Set();
const leads = [];
const skipped = [];
for (const r of raw) {
  const p = r.properties || {};
  const id = String(r.id);
  if (seen.has(id)) { stats.duplicate += 1; continue; }
  seen.add(id);
  const email = String(p.email || '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) { stats.invalidEmail += 1; skipped.push({ contactId: id, reason: 'invalid_email' }); continue; }
  if (p.round_robin_assigned_at) { stats.alreadyAssigned += 1; skipped.push({ contactId: id, reason: 'already_assigned_by_balancer' }); continue; }
  if (p.hubspot_owner_id && !cfg.reassignUnavailableOwner) { stats.alreadyOwned += 1; skipped.push({ contactId: id, reason: 'already_owned' }); continue; }
  if (leads.length >= cfg.maxLeadsPerRun) { stats.overCap += 1; continue; }

  const score = Number.parseFloat(p.hubspotscore);
  leads.push({
    contactId: id,
    email,
    name: [p.firstname, p.lastname].filter(Boolean).join(' ').slice(0, 120) || email,
    company: p.company ? String(p.company).slice(0, 160) : null,
    country: p.country ? String(p.country).toUpperCase() : null,
    state: p.state ? String(p.state).toUpperCase() : null,
    territory: territoryFor(p.country, p.state),
    score: Number.isFinite(score) ? score : null,
    tier: Number.isFinite(score) && score >= cfg.highScoreThreshold ? 'high' : 'standard',
    existingOwnerId: p.hubspot_owner_id ? String(p.hubspot_owner_id) : null,
    createdAt: p.createdate || null,
  });
}
stats.accepted = leads.length;
return [{ json: { leads, skipped, stats } }];

// ─────────────────────────────────────────────────────────────────────────────
// Mock Rep Context (SANDBOX_MODE=true)
// Fictitious roster owners, workload counts and availability in the exact
// shape "Normalize Availability" emits on the live path.
// Profiles: alpha (available), beta (calendar OOO), gamma (PTO), delta (at
// daily capacity), epsilon (public holiday in their region), zeta (available,
// weight 2), eta (EMEA, available).
// ─────────────────────────────────────────────────────────────────────────────
const HOUR = 60 * 60 * 1000;
const inHours = (h) => new Date(Date.now() + h * HOUR).toISOString();
const rep = (id, email, first, assignedToday, openLeads, openDeals, availability) => ({
  ownerId: id, email, name: `${first} (synthetic)`, active: true,
  workload: { assignedToday, openLeads, openDeals, error: null },
  availability,
});
const ok = { status: 'available', until: null, source: 'mock', detail: null };

return [{
  json: {
    source: 'synthetic-fixtures',
    provider: 'mock',
    // Only the synthetic fallback queue exists as an owner; any other FALLBACK_OWNER_EMAIL resolves to none.
    fallbackOwner: $('Config & Safety Gate').first().json.config.fallbackOwnerEmail.toLowerCase() === 'sales.fallback@example.com' ? { ownerId: '84000099', email: 'sales.fallback@example.com' } : null,
    reps: [
      rep('84000001', 'rep.alpha@example.com', 'Alpha', 4, 18, 6, ok),
      rep('84000002', 'rep.beta@example.com', 'Beta', 2, 11, 4, { status: 'ooo', until: inHours(52), source: 'mock-calendar', detail: 'Automatic replies on' }),
      rep('84000003', 'rep.gamma@example.com', 'Gamma', 0, 9, 3, { status: 'pto', until: inHours(120), source: 'mock-pto', detail: 'Vacation' }),
      rep('84000004', 'rep.delta@example.com', 'Delta', 25, 30, 9, ok),
      rep('84000005', 'rep.epsilon@example.com', 'Epsilon', 1, 7, 2, ok),
      rep('84000006', 'rep.zeta@example.com', 'Zeta', 3, 14, 5, ok),
      rep('84000007', 'rep.eta@example.com', 'Eta', 2, 10, 4, ok),
    ],
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Build Rep Workload Queries
// Joins REP_ROSTER with active HubSpot owners and emits one item per rep with
// three CRM Search bodies (limit 1; only `total` is used):
//   assignedToday → contacts owned by the rep with round_robin_assigned_at ≥ 00:00 UTC
//   openLeads     → contacts owned by the rep in OPEN_LEAD_STAGES
//   openDeals     → open deals owned by the rep
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
let roster;
try { roster = JSON.parse(cfg.repRosterJson || '[]'); } catch (e) { throw new Error('REP_ROSTER is not valid JSON.'); }
if (!Array.isArray(roster) || roster.length === 0) throw new Error('REP_ROSTER is empty. Define the rep pool before running outside SANDBOX_MODE.');

const owners = (($input.first().json.results) || []).filter((o) => o.archived !== true);
const byEmail = new Map(owners.map((o) => [String(o.email || '').toLowerCase(), o]));
const now = new Date();
const todayStartMs = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());

const reps = [];
const missing = [];
for (const r of roster) {
  const email = String(r.email || '').toLowerCase();
  const o = byEmail.get(email);
  if (!o) { missing.push(email); continue; }
  const ownerId = String(o.id);
  const owner = { propertyName: 'hubspot_owner_id', operator: 'EQ', value: ownerId };
  reps.push({
    email,
    ownerId,
    name: [o.firstName, o.lastName].filter(Boolean).join(' ') || email,
    assignedTodayBody: { filterGroups: [{ filters: [owner, { propertyName: 'round_robin_assigned_at', operator: 'GTE', value: String(todayStartMs) }] }], limit: 1, properties: ['hs_object_id'] },
    openLeadsBody: { filterGroups: [{ filters: [owner, { propertyName: 'lifecyclestage', operator: 'IN', values: cfg.openLeadStages }] }], limit: 1, properties: ['hs_object_id'] },
    openDealsBody: { filterGroups: [{ filters: [owner, { propertyName: 'hs_is_closed', operator: 'EQ', value: 'false' }] }], limit: 1, properties: ['hs_object_id'] },
  });
}
const fb = byEmail.get(cfg.fallbackOwnerEmail.toLowerCase());
const fallbackOwner = fb ? { ownerId: String(fb.id), email: cfg.fallbackOwnerEmail.toLowerCase() } : null;
if (!reps.length) throw new Error(`No REP_ROSTER email matches an active HubSpot owner (checked ${roster.length}).`);
return reps.map((r, i) => ({ json: { ...r, repIndex: i, rosterMissing: missing, fallbackOwner } }));

// ─────────────────────────────────────────────────────────────────────────────
// Collect Workload
// Joins the three per-rep count responses (aligned by item index) into one
// item. A failed count is recorded as an error; the engine then treats that
// rep as at capacity rather than guessing.
// ─────────────────────────────────────────────────────────────────────────────
const reps = $('Build Rep Workload Queries').all();
const today = $('HubSpot: Count Assigned Today').all();
const leads = $('HubSpot: Count Open Leads').all();
const deals = $input.all();
if (today.length !== reps.length || leads.length !== reps.length || deals.length !== reps.length) {
  throw new Error(`Workload count mismatch: ${reps.length} reps vs ${today.length}/${leads.length}/${deals.length} responses. Unpin the count nodes or align their items.`);
}
const total = (r) => (r && r.json && !r.json.error && Number.isFinite(Number(r.json.total)) ? Number(r.json.total) : null);

return [{
  json: {
    rosterMissing: reps[0] ? reps[0].json.rosterMissing : [],
    fallbackOwner: reps[0] ? reps[0].json.fallbackOwner : null,
    reps: reps.map((r, i) => {
      const w = { assignedToday: total(today[i]), openLeads: total(leads[i]), openDeals: total(deals[i]) };
      const failed = Object.entries(w).filter(([, v]) => v === null).map(([k]) => k);
      return { ownerId: r.json.ownerId, email: r.json.email, name: r.json.name, active: true, workload: { ...w, error: failed.length ? `count failed: ${failed.join(', ')}` : null } };
    }),
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Build Calendar Requests
// Prepares the availability lookup for CALENDAR_PROVIDER over the window
// [now, now + AVAILABILITY_WINDOW_HOURS]:
//   microsoft → one Graph getSchedule request for all reps (status "oof")
//   google    → one events.list request per rep (eventTypes=outOfOffice)
//   pto_api   → one request to PTO_API_URL for the window
//   none      → no request; holidays and working hours still apply
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { reps } = $input.first().json;
const start = new Date();
const end = new Date(start.getTime() + cfg.availabilityWindowHours * 3600000);
const window = { start: start.toISOString(), end: end.toISOString() };

if (cfg.calendarProvider === 'google') {
  return reps.map((r, i) => ({
    json: {
      provider: 'google', repIndex: i, email: r.email, window,
      url: `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(r.email)}/events?eventTypes=outOfOffice&singleEvents=true&timeMin=${encodeURIComponent(window.start)}&timeMax=${encodeURIComponent(window.end)}&maxResults=10`,
    },
  }));
}
if (cfg.calendarProvider === 'microsoft') {
  if (!cfg.calendarOrganizerUpn) throw new Error('CALENDAR_ORGANIZER_UPN is required for CALENDAR_PROVIDER=microsoft.');
  return [{
    json: {
      provider: 'microsoft', window,
      url: `https://graph.microsoft.com/v1.0/users/${encodeURIComponent(cfg.calendarOrganizerUpn)}/calendar/getSchedule`,
      body: { schedules: reps.map((r) => r.email), startTime: { dateTime: window.start.slice(0, 19), timeZone: 'UTC' }, endTime: { dateTime: window.end.slice(0, 19), timeZone: 'UTC' }, availabilityViewInterval: 30 },
    },
  }];
}
if (cfg.calendarProvider === 'pto_api') {
  if (!cfg.ptoApiUrl) throw new Error('PTO_API_URL is required for CALENDAR_PROVIDER=pto_api.');
  return [{ json: { provider: 'pto_api', window, url: `${cfg.ptoApiUrl}${cfg.ptoApiUrl.includes('?') ? '&' : '?'}start=${encodeURIComponent(window.start)}&end=${encodeURIComponent(window.end)}` } }];
}
return [{ json: { provider: 'none', window } }];

// ─────────────────────────────────────────────────────────────────────────────
// Normalize Availability
// Converts whichever calendar/PTO response ran into one availability record
// per rep: available | ooo | pto | unknown (lookup failed). Holidays and
// working hours are evaluated later by the engine from configuration.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { reps, rosterMissing, fallbackOwner } = $('Collect Workload').first().json;
const reqs = $('Build Calendar Requests').all().map((i) => i.json);
const provider = reqs[0] ? reqs[0].provider : 'none';
const window = reqs[0] ? reqs[0].window : { start: new Date().toISOString(), end: new Date().toISOString() };
const safeAll = (name) => { try { return $(name).all().map((i) => i.json); } catch (e) { return null; } };
const ws = Date.parse(window.start);
const we = Date.parse(window.end);
const overlaps = (s, e) => Number.isFinite(s) && Number.isFinite(e) && s < we && e > ws;
const graphTime = (t) => (t && t.dateTime ? Date.parse(`${String(t.dateTime).replace(/Z$/, '')}${/utc/i.test(t.timeZone || 'UTC') ? 'Z' : ''}`) : NaN);
const avail = (status, until, detail) => ({ status, until: until ? new Date(until).toISOString() : null, source: provider, detail: detail || null });

const byEmail = new Map();
if (provider === 'microsoft') {
  const resp = (safeAll('Microsoft Graph: Get Schedule') || [])[0] || {};
  if (resp.error) for (const r of reps) byEmail.set(r.email, avail('unknown', null, String(resp.error.message || resp.error).slice(0, 160)));
  for (const s of Array.isArray(resp.value) ? resp.value : []) {
    const email = String(s.scheduleId || '').toLowerCase();
    if (s.error) { byEmail.set(email, avail('unknown', null, String(s.error.message || s.error.responseCode || 'error').slice(0, 160))); continue; }
    const oof = (s.scheduleItems || []).filter((it) => String(it.status).toLowerCase() === 'oof' && overlaps(graphTime(it.start), graphTime(it.end)));
    byEmail.set(email, oof.length ? avail('ooo', Math.max(...oof.map((it) => graphTime(it.end))), 'Calendar shows out of office') : avail('available'));
  }
} else if (provider === 'google') {
  const resps = safeAll('Google Calendar: OOO Events') || [];
  reqs.forEach((rq, i) => {
    const resp = resps[i] || {};
    if (resp.error) { byEmail.set(rq.email, avail('unknown', null, String(resp.error.message || resp.error).slice(0, 160))); return; }
    const items = (resp.items || []).filter((ev) => (ev.eventType || 'outOfOffice') === 'outOfOffice' && overlaps(Date.parse(ev.start?.dateTime || ev.start?.date), Date.parse(ev.end?.dateTime || ev.end?.date)));
    byEmail.set(rq.email, items.length ? avail('ooo', Math.max(...items.map((ev) => Date.parse(ev.end?.dateTime || ev.end?.date))), 'Out-of-office event') : avail('available'));
  });
} else if (provider === 'pto_api') {
  const resp = (safeAll('PTO API: List Time Off') || [])[0] || {};
  if (resp.error) for (const r of reps) byEmail.set(r.email, avail('unknown', null, String(resp.error.message || resp.error).slice(0, 160)));
  else {
    for (const r of reps) byEmail.set(r.email, avail('available'));
    const entries = resp.entries || resp.timeOff || resp.data || [];
    for (const e of Array.isArray(entries) ? entries : []) {
      const email = String(e.email || e.employeeEmail || '').toLowerCase();
      if (!byEmail.has(email) || e.approved === false) continue;
      const s = Date.parse(e.start || e.startDate);
      const en = Date.parse(e.end || e.endDate);
      if (overlaps(s, en)) byEmail.set(email, avail('pto', en, String(e.type || 'time off').slice(0, 40)));
    }
  }
}

return [{
  json: {
    source: 'hubspot',
    provider,
    rosterMissing,
    fallbackOwner,
    reps: reps.map((r) => ({ ...r, availability: byEmail.get(r.email) || avail(provider === 'none' ? 'available' : 'unknown', null, provider === 'none' ? 'no calendar provider' : 'not returned') })),
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Weighted Round-Robin Assignment Engine
// 1. Builds each rep's eligibility: active owner, calendar/PTO availability,
//    public holiday in the rep's region (HOLIDAY_CALENDAR, rep-local date),
//    working hours (OFF_HOURS_POLICY), daily lead cap, open-lead and
//    open-deal caps. Every exclusion is recorded with a reason.
// 2. For each lead: territory pool (+ tier) → cross-territory pool
//    (ALLOW_CROSS_TERRITORY) → FALLBACK_OWNER_EMAIL, using smooth weighted
//    round-robin. Assignments inside the run count toward capacity.
// 3. Persists smooth-WRR state per pool in workflow static data (production
//    executions only).
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { leads } = $('Normalize Leads').first().json;
const ctx = $input.first().json;
const now = new Date();

// ── Roster, holidays ──────────────────────────────────────────────────────
const SANDBOX_ROSTER = [
  { email: 'rep.alpha@example.com', weight: 1, territories: ['NA'], region: 'US', timezone: 'America/New_York' },
  { email: 'rep.beta@example.com', weight: 1, territories: ['NA'], region: 'US', timezone: 'America/New_York' },
  { email: 'rep.gamma@example.com', weight: 1, territories: ['NA'], region: 'US', timezone: 'America/Chicago' },
  { email: 'rep.delta@example.com', weight: 1, territories: ['NA'], region: 'US', timezone: 'America/Denver' },
  { email: 'rep.epsilon@example.com', weight: 1, territories: ['NA', 'APAC'], region: 'IN', timezone: 'Asia/Kolkata' },
  { email: 'rep.zeta@example.com', weight: 2, territories: ['NA'], tiers: ['high', 'standard'], region: 'US', timezone: 'America/Los_Angeles' },
  { email: 'rep.eta@example.com', weight: 1, territories: ['EMEA'], region: 'DE', timezone: 'Europe/Berlin' },
];
const localDate = (tz) => {
  try { return new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now); } catch (e) { return now.toISOString().slice(0, 10); }
};
const parse = (s, fallback, label) => { if (!s) return fallback; try { return JSON.parse(s); } catch (e) { throw new Error(`${label} is not valid JSON.`); } };
const roster = parse(cfg.repRosterJson, cfg.sandboxMode ? SANDBOX_ROSTER : [], 'REP_ROSTER');
const holidays = parse(cfg.holidayCalendarJson, cfg.sandboxMode ? { IN: [localDate('Asia/Kolkata')] } : {}, 'HOLIDAY_CALENDAR');
const rosterByEmail = new Map(roster.map((r) => [String(r.email).toLowerCase(), r]));

function localClock(tz) {
  try {
    const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: tz, hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit' }).formatToParts(now).map((p) => [p.type, p.value]));
    const dow = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(parts.weekday);
    return { dow, minutes: (Number(parts.hour) % 24) * 60 + Number(parts.minute) };
  } catch (e) { return { dow: now.getUTCDay(), minutes: now.getUTCHours() * 60 + now.getUTCMinutes() }; }
}
const [whStart, whEnd] = cfg.workingHours.split('-').map((t) => { const [h, m] = t.split(':').map(Number); return h * 60 + (m || 0); });

// ── Eligibility ───────────────────────────────────────────────────────────
const unavailable = new Set(cfg.unavailableEmails.map((e) => e.toLowerCase()));
const reps = ctx.reps.filter((r) => rosterByEmail.has(r.email)).map((r) => {
  const ro = rosterByEmail.get(r.email);
  const tz = ro.timezone || 'UTC';
  const reasons = [];
  if (!r.active) reasons.push('inactive_owner');
  if (unavailable.has(r.email)) reasons.push('manually_unavailable');
  const a = r.availability || { status: 'unknown' };
  if (a.status === 'ooo') reasons.push('calendar_ooo');
  if (a.status === 'pto') reasons.push('pto');
  if (a.status === 'unknown' && cfg.calendarFailurePolicy === 'exclude') reasons.push('availability_unknown');
  if (ro.region && (holidays[ro.region] || []).includes(localDate(tz))) reasons.push(`holiday_${ro.region}`);
  const clock = localClock(tz);
  const offHours = !cfg.workingDays.includes(clock.dow) || clock.minutes < whStart || clock.minutes >= whEnd;
  if (offHours && cfg.offHoursPolicy === 'exclude') reasons.push('outside_working_hours');
  const w = r.workload || {};
  if (w.error) reasons.push('workload_unknown');
  const maxDaily = Number(ro.maxDailyLeads) || cfg.maxDailyLeadsPerRep;
  const maxOpenLeads = Number(ro.maxOpenLeads) || cfg.maxOpenLeadsPerRep;
  const maxOpenDeals = Number(ro.maxOpenDeals) || cfg.maxOpenDealsPerRep;
  if (Number(w.assignedToday) >= maxDaily) reasons.push('daily_capacity_reached');
  if (maxOpenLeads > 0 && Number(w.openLeads) >= maxOpenLeads) reasons.push('open_lead_capacity_reached');
  if (maxOpenDeals > 0 && Number(w.openDeals) >= maxOpenDeals) reasons.push('open_deal_capacity_reached');
  return {
    ...r,
    weight: Math.max(1, Math.min(10, Number(ro.weight) || 1)),
    territories: (ro.territories || ['*']).map(String),
    tiers: (ro.tiers || ['high', 'standard']).map(String),
    region: ro.region || null,
    timezone: tz,
    offHours,
    limits: { maxDaily, maxOpenLeads, maxOpenDeals },
    assignedThisRun: 0,
    eligible: reasons.length === 0,
    exclusions: reasons,
  };
});

// ── Smooth weighted round-robin state ─────────────────────────────────────
let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
const persist = Boolean(store) && !cfg.sandboxMode && cfg.executionMode === 'production';
const state = persist ? store : {};
state.swrr = state.swrr || {};

function pick(poolKey, candidates) {
  const live = candidates.filter((r) => r.eligible && (Number(r.workload.assignedToday) + r.assignedThisRun) < r.limits.maxDaily && (r.limits.maxOpenLeads <= 0 || Number(r.workload.openLeads) + r.assignedThisRun < r.limits.maxOpenLeads));
  if (!live.length) return null;
  const cw = state.swrr[poolKey] || {};
  const total = live.reduce((n, r) => n + r.weight, 0);
  let best = null;
  for (const r of live) {
    cw[r.email] = (cw[r.email] || 0) + r.weight;
    if (!best || cw[r.email] > cw[best.email]) best = r;
  }
  cw[best.email] -= total;
  for (const k of Object.keys(cw)) if (!live.some((r) => r.email === k)) delete cw[k];
  state.swrr[poolKey] = cw;
  return best;
}

// ── Assignment ────────────────────────────────────────────────────────────
const fallbackRep = reps.find((r) => r.email === cfg.fallbackOwnerEmail.toLowerCase());
const fallbackOwnerId = fallbackRep ? fallbackRep.ownerId : (ctx.fallbackOwner && ctx.fallbackOwner.email === cfg.fallbackOwnerEmail.toLowerCase() ? ctx.fallbackOwner.ownerId : null);
const decisions = leads.map((lead) => {
  if (lead.existingOwnerId) {
    const ownerRep = reps.find((r) => r.ownerId === lead.existingOwnerId);
    if (!ownerRep || ownerRep.eligible) return { lead, rule: 'kept_existing_owner', rep: ownerRep ? ownerRep.email : null, ownerId: lead.existingOwnerId, write: false, pool: null, skipped: [] };
  }
  const inTerritory = reps.filter((r) => (r.territories.includes(lead.territory) || r.territories.includes('*')) && r.tiers.includes(lead.tier));
  const skipped = inTerritory.filter((r) => !r.eligible).map((r) => `${r.email.split('@')[0]}:${r.exclusions[0]}`);
  // One rotation per territory; the tier only narrows the candidate set, so weights hold across tiers.
  let chosen = pick(`territory:${lead.territory}`, inTerritory);
  let rule = 'territory_weighted_round_robin';
  let pool = lead.territory;
  if (!chosen && cfg.allowCrossTerritory) {
    chosen = pick('global', reps.filter((r) => r.tiers.includes(lead.tier)));
    rule = 'cross_territory_weighted_round_robin';
    pool = 'global';
  }
  if (chosen) {
    chosen.assignedThisRun += 1;
    return { lead, rule, rep: chosen.email, ownerId: chosen.ownerId, write: true, pool, skipped };
  }
  return fallbackOwnerId
    ? { lead, rule: 'fallback_owner', rep: cfg.fallbackOwnerEmail, ownerId: fallbackOwnerId, write: true, pool: null, skipped }
    : { lead, rule: 'unassigned_no_available_rep', rep: null, ownerId: null, write: false, pool: null, skipped };
});

return [{
  json: {
    decisions,
    reps: reps.map(({ assignedThisRun, ...r }) => ({ ...r, assignedThisRun })),
    engine: {
      provider: ctx.provider,
      rosterSize: roster.length,
      rosterMissing: ctx.rosterMissing || [],
      eligibleReps: reps.filter((r) => r.eligible).map((r) => r.email),
      excludedReps: reps.filter((r) => !r.eligible).map((r) => ({ email: r.email, reasons: r.exclusions })),
      statePersisted: persist,
    },
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Compose Assignment Payloads
// Builds the contact batch update (owner + round_robin_* audit properties)
// and assignment notes (note → contact association 202).
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { decisions, engine } = $input.first().json;
const nowIso = new Date().toISOString();
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const RULE = { territory_weighted_round_robin: 'territory weighted round-robin', cross_territory_weighted_round_robin: 'cross-territory weighted round-robin', fallback_owner: 'fallback owner' };

const writes = decisions.filter((d) => d.write);
const updates = writes.map((d) => ({
  id: d.lead.contactId,
  properties: {
    hubspot_owner_id: d.ownerId,
    round_robin_assigned_at: nowIso,
    round_robin_rule: d.rule,
    round_robin_rep_email: d.rep,
    round_robin_pool: d.pool || '',
    round_robin_skipped_reps: d.skipped.join('; ').slice(0, 500),
  },
}));
const notes = cfg.logAssignmentNotes ? writes.map((d) => ({
  properties: {
    hs_timestamp: nowIso,
    hs_note_body: `<p><strong>Lead assigned by round-robin balancer</strong></p><p>Assigned to ${esc(d.rep)} via ${esc(RULE[d.rule] || d.rule)}${d.pool ? ` (pool ${esc(d.pool)})` : ''}. Territory: ${esc(d.lead.territory)} · Tier: ${esc(d.lead.tier)}${d.lead.score !== null ? ` · Score: ${esc(d.lead.score)}` : ''}.</p>${d.skipped.length ? `<p>Skipped reps: ${esc(d.skipped.join(', '))}</p>` : ''}<p><em>n8n-hubspot-round-robin-pto-holiday-aware-balancer (dhRobin Systems), run ${esc(cfg.runId)}.</em></p>`,
  },
  associations: [{ to: { id: d.lead.contactId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 202 }] }],
})) : [];

const chunk = (a) => { const o = []; for (let i = 0; i < a.length; i += 100) o.push(a.slice(i, i + 100)); return o; };
const byRep = writes.reduce((m, d) => ({ ...m, [d.rep]: (m[d.rep] || 0) + 1 }), {});
return [{
  json: {
    dryRun: cfg.dryRun,
    assignLeads: cfg.assignLeads,
    counts: { decisions: decisions.length, assignments: updates.length, notes: notes.length, unassigned: decisions.filter((d) => d.rule === 'unassigned_no_available_rep').length, kept: decisions.filter((d) => d.rule === 'kept_existing_owner').length },
    updateBatches: chunk(updates),
    noteBatches: chunk(notes),
    distribution: byRep,
    engine,
    decisions: decisions.map((d) => ({ contactId: d.lead.contactId, territory: d.lead.territory, tier: d.lead.tier, rule: d.rule, rep: d.rep, pool: d.pool, skipped: d.skipped })),
  },
}];

// Collapse batch responses so the next stage runs once.
const r = $input.all().map((i) => i.json);
return [{ json: { batches: r.length, written: r.reduce((n, x) => n + (Array.isArray(x.results) ? x.results.length : 0), 0) } }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Final node on every path: intake, lead validation, rep eligibility,
// per-lead decisions, distribution and HubSpot write results in one record,
// also written to the n8n log (contact IDs only, no lead emails).
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const parsed = $('Parse & Validate Events').first().json;
const safeFirst = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const safeAll = (n) => { try { return $(n).all().map((i) => i.json); } catch (e) { return []; } };
const count = (rs) => rs.reduce((n, r) => n + (Array.isArray(r.results) ? r.results.length : 0), 0);
const errs = (rs) => rs.reduce((n, r) => n + (Array.isArray(r.errors) ? r.errors.length : 0), 0);

const normalized = safeFirst('Normalize Leads');
const composed = safeFirst('Compose Assignment Payloads');
const updates = safeAll('HubSpot: Batch Update Contact Owners');
const notes = safeAll('HubSpot: Batch Create Assignment Notes');

let outcome = 'no_leads';
if (composed) outcome = composed.dryRun ? 'dry_run' : !composed.assignLeads ? 'assignment_disabled' : updates.length ? 'assigned' : 'nothing_to_assign';
else if (normalized && normalized.leads.length === 0) outcome = 'no_eligible_leads';

const summary = {
  outcome,
  runId: cfg.runId,
  mode: parsed.mode,
  signature: parsed.signature,
  sandbox: cfg.sandboxMode,
  intake: parsed.counters,
  leadValidation: normalized ? normalized.stats : null,
  skippedLeads: normalized ? normalized.skipped : [],
  engine: composed ? composed.engine : null,
  counts: composed ? composed.counts : null,
  distribution: composed ? composed.distribution : {},
  decisions: composed ? composed.decisions : [],
  hubspot: { ownersUpdated: count(updates), notesCreated: count(notes), errors: errs(updates) + errs(notes) },
  finishedAt: new Date().toISOString(),
};
console.log(`[round-robin-balancer] ${JSON.stringify({ outcome, runId: cfg.runId, mode: parsed.mode, distribution: summary.distribution, excluded: summary.engine ? summary.engine.excludedReps : [], hubspot: summary.hubspot })}`);
return [{ json: summary }];
